import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"飞琼伴侣","description":"","frontmatter":{"title":"飞琼伴侣","date":"2026-11-20T00:00:00.000Z","seq":2,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词"},"headers":[],"relativePath":"blogs/全宋词·柳永/飞琼伴侣.md","filePath":"blogs/全宋词·柳永/飞琼伴侣.md"}'),o={name:"blogs/全宋词·柳永/飞琼伴侣.md"};function l(c,a,n,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="飞琼伴侣" tabindex="-1">飞琼伴侣 <a class="header-anchor" href="#飞琼伴侣" aria-label="Permalink to &quot;飞琼伴侣&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　玉女摇仙佩</p><div class="poem"><p class="poem-stanza">飞琼伴侣，偶别珠宫，未返神仙行缀。</p><p class="poem-stanza">取次梳妆，寻常言语，有得几多姝丽。</p><p class="poem-stanza">拟把名花比。</p><p class="poem-stanza">恐旁人笑我，谈何容易。</p><p class="poem-stanza">细思算、奇葩艳卉，惟是深红浅白而已。</p><p class="poem-stanza">争如这多情，占得人间，千娇百媚。</p><p class="poem-stanza">须信画堂绣阁，皓月清风，忍把光阴轻弃。</p><p class="poem-stanza">自古及今、佳人才子，少得当年双美。</p><p class="poem-stanza">且恁相偎依。</p><p class="poem-stanza">未消得、怜我多才多艺。</p><p class="poem-stanza">愿妳妳、兰心蕙性，枕前言下，表余深意。</p><p class="poem-stanza">为盟誓。</p><p class="poem-stanza">今生断不孤鸳被。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
